package com.sisge.ms.entity;
import com.sisge.ms.model.ImportStatus;
import jakarta.persistence.*; import java.time.Instant; import com.sisge.ms.entity.Organizacion; import com.sisge.ms.entity.Usuario;
@Entity @Table(name="importaciones") public class Importacion {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="organizacion_id",nullable=false) private Organizacion organizacion; @Column(name="archivo_origen",nullable=false) private String archivoOrigen; @Enumerated(EnumType.STRING) @Column(nullable=false) private ImportStatus estado=ImportStatus.EN_PROCESO; @ManyToOne @JoinColumn(name="creado_por_usuario_id",nullable=false) private Usuario creadoPor; @ManyToOne @JoinColumn(name="revisado_por_usuario_id") private Usuario revisadoPor; @Column(name="fecha_creacion",nullable=false) private Instant fechaCreacion=Instant.now(); private Instant fechaEnvioRevision; private Instant fechaRevision; private Instant fechaCierre; @Column(columnDefinition="TEXT") private String motivoObservacion; @Column(columnDefinition="TEXT") private String motivoRechazo; private int cantidadFilas; private int cantidadFilasValidas; private int cantidadFilasConError; @Version private Long version;
 public Long getId(){return id;} public Organizacion getOrganizacion(){return organizacion;} public String getArchivoOrigen(){return archivoOrigen;} public ImportStatus getEstado(){return estado;} public Usuario getCreadoPor(){return creadoPor;} public int getCantidadFilas(){return cantidadFilas;} public int getCantidadFilasValidas(){return cantidadFilasValidas;} public int getCantidadFilasConError(){return cantidadFilasConError;} public String getMotivoObservacion(){return motivoObservacion;} public String getMotivoRechazo(){return motivoRechazo;}
 public Instant getFechaCreacion(){return fechaCreacion;} public Instant getFechaEnvioRevision(){return fechaEnvioRevision;} public Instant getFechaRevision(){return fechaRevision;} public Instant getFechaCierre(){return fechaCierre;}
 public void setOrganizacion(Organizacion o){organizacion=o;} public void setArchivoOrigen(String a){archivoOrigen=a;} public void setCreadoPor(Usuario u){creadoPor=u;} public void setCantidadFilas(int n){cantidadFilas=n;} public void recount(int valid,int errors){cantidadFilasValidas=valid;cantidadFilasConError=errors;} public void submit(){estado=ImportStatus.PENDIENTE_REVISION;fechaEnvioRevision=Instant.now();} public void observe(Usuario u,String reason){estado=ImportStatus.OBSERVADA;revisadoPor=u;fechaRevision=Instant.now();motivoObservacion=reason;} public void reject(Usuario u,String reason){estado=ImportStatus.RECHAZADA;revisadoPor=u;fechaRevision=Instant.now();motivoRechazo=reason;} public void close(Usuario u){estado=ImportStatus.CERRADA;revisadoPor=u;fechaRevision=Instant.now();fechaCierre=Instant.now();}
}
